mapper.select:
select a.id, a.title, a.category_id, a.cover_url, a.summary, a.location, a.start_time, a.end_time, a.signup_deadline, a.capacity, a.signed_count, a.status, a.organizer_id, a.create_time, c.name as category_name, u.real_name as organizer_name, r.status as reg_status from activity a left join activity_category c on c.id = a.category_id left join sys_user u on u.id = a.organizer_id left join activity_registration r on r.activity_id = a.id and r.user_id = #{userId}
and a.category_id = #{q.categoryId}
and (a.title like concat('%', #{q.keyword}, '%') or a.summary like concat('%', #{q.keyword}, '%'))
and a.status = #{q.status}
and a.organizer_id = #{q.organizerId}
and a.status = 2 and a.end_time > now()
order by a.signed_count desc, a.start_time asc
order by a.start_time desc, a.id desc
